WITH orders_by_store AS (SELECT store_id, SUM(shipping_fee) AS total_shipping_fee, COUNT(CASE WHEN channel = 'partner' THEN 1 END) AS partner_count FROM orders WHERE shipping_fee < 35 GROUP BY store_id) SELECT s.id, s.sqft, s.opened_date, obs.total_shipping_fee, obs.partner_count FROM stores s LEFT OUTER JOIN orders_by_store obs ON s.id = obs.store_id WHERE obs.total_shipping_fee > 140 ORDER BY s.id ASC;
